record.field:
for activity in records:
    picking = env['stock.picking'].browse(activity.res_id).exists()

    result = picking.button_validate()
    is_backorder_wizard = (
        isinstance(result, dict)
        and result.get('res_model') == 'stock.backorder.confirmation'
    )

    if not is_backorder_wizard:
        raise UserError(
            'Phiếu kho %s không trả về wizard Backorder.'
            % picking.display_name
        )

    decision_second = datetime.datetime.now().second
    create_backorder = decision_second % 9 != 0
    wizard_context = dict(result.get('context', {}))
    wizard = env['stock.backorder.confirmation'].with_context(
        wizard_context
    ).create({
        'pick_ids': [(6, 0, picking.ids)],
        'backorder_confirmation_line_ids': [(0, 0, {
            'picking_id': picking.id,
            'to_backorder': create_backorder,
        })],
    })

    if create_backorder:
        summary = 'Đã chọn tạo Backorder cho %s' % picking.display_name
        note = (
            'Giây chạy server action là %s, không chia hết cho 9. '
            'Hệ thống đã chọn tạo Backorder và cần tiếp tục xử lý '
            'phiếu Backorder được sinh ra.'
            % decision_second
        )
    else:
        summary = 'Không cần tạo Backorder cho %s' % picking.display_name
        note = (
            'Giây chạy server action là %s, chia hết cho 9. '
            'Hệ thống đã chọn không tạo Backorder.'
            % decision_second
        )

    picking.activity_schedule(
        'mail.mail_activity_data_todo',
        date_deadline=activity.date_deadline,
        user_id=activity.user_id.id,
        summary=summary,
        note=note,
    )
